@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#07100f;--paper:#edf0e7;--muted:#a9b0a7;--acid:#d4fc58;--orange:#ff6845;--line:rgba(237,240,231,.16);--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper)}body{font-family:var(--mono);user-select:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:450px;overflow:hidden;background:#0d1715}#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.scanlines{pointer-events:none;position:absolute;inset:0;z-index:2;opacity:.1;background:repeating-linear-gradient(0deg,transparent 0px,transparent 2px,rgba(0,0,0,.4) 3px,rgba(0,0,0,.4) 4px);mix-blend-mode:multiply}.topbar{position:absolute;z-index:10;top:0;left:0;right:0;height:76px;padding:0 5.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(237,240,231,.13);background:linear-gradient(180deg,rgba(4,11,10,.78),transparent)}.brand{display:flex;align-items:center;gap:12px;color:var(--paper);text-decoration:none;font:800 21px var(--display);letter-spacing:.04em}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--acid);color:var(--acid);font:800 21px var(--display);transform:skew(-8deg)}.slash{color:var(--acid)}.top-center,.objective-tag{font-size:10px;letter-spacing:.16em;color:#c3ccc2}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 11px var(--acid);margin-right:9px;animation:pulse 1.6s infinite}.icon-btn{border:1px solid var(--line);background:rgba(5,12,11,.48);padding:10px 13px;font-size:13px;letter-spacing:.1em;cursor:pointer}.icon-btn span{font-size:9px;color:var(--muted);margin-left:7px}.screen{position:absolute;z-index:5;inset:76px 0 0;display:flex}.menu-screen{align-items:center;background:linear-gradient(90deg,rgba(4,11,10,.93) 0%,rgba(4,11,10,.79) 35%,rgba(4,11,10,.11) 77%),linear-gradient(0deg,rgba(4,11,10,.48),transparent 40%)}.menu-content{margin-left:clamp(34px,10.2vw,164px);margin-top:-6px;width:min(460px,45vw)}.eyebrow{font-size:10px;letter-spacing:.15em;color:var(--acid);margin:0 0 19px}.eyebrow span{opacity:.6}.menu-content h1,.modal-card h2{font:900 clamp(58px,7vw,98px)/.79 var(--display);letter-spacing:-.025em;margin:0;text-transform:uppercase}.menu-content h1 span,.modal-card h2 span{color:var(--acid)}.intro{margin:20px 0 26px;color:#c0c6bc;font-size:12px;line-height:1.6}.mode-label{font-size:9px;letter-spacing:.17em;color:#9da69b;margin-bottom:9px}.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mode-card{height:87px;position:relative;text-align:left;padding:13px 15px;border:1px solid rgba(237,240,231,.22);background:rgba(10,20,18,.62);cursor:pointer;transition:.2s}.mode-card:hover,.mode-card.selected{border-color:var(--acid);background:rgba(31,43,29,.68)}.mode-index{position:absolute;right:12px;top:11px;color:#778077;font-size:9px}.mode-icon{font-size:18px;color:var(--acid);display:block;height:25px}.mode-card strong{display:block;font:700 16px var(--display);letter-spacing:.04em}.mode-card small{display:block;color:#9fa89e;font-size:8px;letter-spacing:.08em;margin-top:3px}.mode-check{position:absolute;right:11px;bottom:12px;color:var(--acid);opacity:0}.mode-card.selected .mode-check{opacity:1}.deploy-btn{margin-top:14px;width:100%;height:52px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;background:var(--acid);border:0;color:#101710;cursor:pointer;font:800 17px var(--display);letter-spacing:.07em;transition:background .2s,transform .2s}.deploy-btn:hover{background:#e2ff86;transform:translateY(-2px)}.deploy-btn b{font:500 22px var(--mono)}.controls-note{margin-top:14px;font-size:8px;letter-spacing:.07em;color:#969f95;white-space:nowrap}.controls-note span{color:#e3e7dd}.controls-note i{color:var(--acid);padding:0 5px;font-style:normal}.menu-side-note{position:absolute;right:5.2%;bottom:8%;writing-mode:vertical-rl;transform:rotate(180deg);font-size:9px;letter-spacing:.19em;color:#c0c8be}.menu-side-note span{color:var(--acid);padding:8px 0}.loader{position:absolute;z-index:30;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;background:#07100f;gap:15px;letter-spacing:.16em;font-size:10px;color:#b9c3b6;transition:opacity .5s}.loader.done{opacity:0;pointer-events:none}.loader-mark{width:48px;height:48px;border:1px solid var(--acid);display:grid;place-items:center;color:var(--acid);font:800 30px var(--display);animation:loaderpulse .8s infinite alternate}.loader i{width:130px;height:2px;background:linear-gradient(90deg,var(--acid) 45%,rgba(212,252,88,.12) 45%)}
.hud{position:absolute;z-index:4;inset:76px 0 0;pointer-events:none}.hidden{display:none!important}.hud-top-left{position:absolute;left:5.2%;top:26px;display:flex;gap:26px;align-items:start}.stage-card{min-width:80px;border-right:1px solid var(--line);padding-right:17px}.hud-label{display:block;font-size:8px;letter-spacing:.15em;color:#abb4a9}.stage-card strong{font:700 44px/.95 var(--display);color:var(--acid)}.stage-total{font-size:11px;color:#aab1a7}.boss-card strong{display:block;font:700 21px var(--display);letter-spacing:.04em;margin:4px 0}.boss-meta{display:flex;gap:15px;color:#adb6aa;font-size:8px;letter-spacing:.1em}.enemy-count b{color:var(--acid)}.hud-top-right{position:absolute;right:5.2%;top:24px;display:flex;align-items:center;gap:18px}.objective-tag{font-size:8px;letter-spacing:.13em}.pause-btn{pointer-events:auto}.boss-health-wrap{position:absolute;top:105px;left:50%;transform:translateX(-50%);width:min(360px,39vw)}.bar-caption{display:flex;justify-content:space-between;color:#c2c9bd;font-size:8px;letter-spacing:.13em;margin-bottom:6px}.boss-health{height:4px;background:rgba(237,240,231,.24);overflow:hidden}.boss-health i{display:block;width:100%;height:100%;background:var(--orange);box-shadow:0 0 10px var(--orange);transition:width .22s}.crosshair{position:absolute;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);opacity:.86}.crosshair i{position:absolute;background:var(--acid)}.crosshair i:nth-child(1){width:1px;height:7px;top:0;left:11px}.crosshair i:nth-child(2){width:1px;height:7px;bottom:0;left:11px}.crosshair i:nth-child(3){width:7px;height:1px;left:0;top:11px}.crosshair i:nth-child(4){width:7px;height:1px;right:0;top:11px}.crosshair b{position:absolute;width:3px;height:3px;background:var(--acid);left:10px;top:10px;border-radius:50%}.hit-marker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font:700 26px var(--mono);color:var(--acid);opacity:0;transition:opacity .08s;text-shadow:0 0 8px var(--acid)}.hit-marker.show{opacity:1}.damage-flash{position:absolute;inset:0;background:rgba(255,45,20,.25);opacity:0;transition:opacity .12s}.hud-bottom-left{position:absolute;left:5.2%;bottom:33px;width:215px}.player-readout{display:flex;gap:11px;align-items:center;margin-bottom:8px}.health-icon{width:30px;height:30px;border:1px solid var(--acid);color:var(--acid);font:500 23px var(--mono);display:grid;place-items:center}.health-line strong{font:700 28px/.95 var(--display)}.health-line span{font-size:9px;color:#a5aea3}.health-bar{height:4px;background:rgba(237,240,231,.22)}.health-bar i{display:block;width:100%;height:100%;background:var(--acid);transition:width .2s}.squad-status{font-size:8px;letter-spacing:.1em;color:#bac4b7;margin-top:10px}.squad-status span{color:var(--acid);font-size:12px}.squad-status b{color:var(--acid);margin-left:5px}.hud-bottom-right{position:absolute;right:5.2%;bottom:31px;display:flex;align-items:end;gap:22px}.ammo-block{text-align:right}.ammo-block .hud-label{margin-bottom:3px}.ammo-block .hud-label i{color:var(--acid);font-style:normal}.ammo-block>div strong{font:700 39px/.9 var(--display)}.ammo-reserve{font-size:11px;color:#a5aea3}.reload-btn{pointer-events:auto;border:1px solid var(--line);background:rgba(5,12,11,.58);padding:10px 12px;color:var(--acid);font-size:16px;cursor:pointer}.reload-btn span{font-size:8px;letter-spacing:.1em;color:#e3e8de}.reload-btn kbd{font:8px var(--mono);border:1px solid var(--line);padding:3px 4px;margin-left:6px;color:#a3aca2}.toast{position:absolute;top:150px;left:50%;transform:translateX(-50%);font:700 20px var(--display);letter-spacing:.12em;color:var(--acid);text-shadow:0 2px 14px #000;white-space:nowrap;opacity:0;transition:opacity .2s}.toast.show{opacity:1}.modal-screen{inset:0;align-items:center;justify-content:center;background:rgba(4,10,9,.78);backdrop-filter:blur(7px);z-index:12}.modal-card{width:min(410px,90vw);border:1px solid rgba(212,252,88,.42);background:rgba(8,17,15,.95);padding:38px 42px;box-shadow:0 24px 100px #000}.modal-card h2{font-size:58px}.modal-card>p:not(.eyebrow){font-size:11px;color:#b5beb2;line-height:1.6;margin:18px 0}.text-btn{display:block;margin:18px auto 0;border:0;background:none;color:#abb4a9;text-decoration:underline;font-size:9px;letter-spacing:.12em;cursor:pointer}.run-stats{display:flex;gap:32px;margin:22px 0 2px}.run-stats div{display:flex;flex-direction:column}.run-stats strong{font:700 34px var(--display);color:var(--acid)}.run-stats span{font-size:8px;letter-spacing:.1em;color:#a5aea3}.mobile-controls{display:none;pointer-events:auto}.move-pad{position:absolute;left:22px;bottom:25px}.move-pad button,.mobile-fire{width:40px;height:40px;border:1px solid rgba(212,252,88,.46);background:rgba(8,17,15,.65);color:var(--acid);font-size:14px}.move-pad>button{display:block;margin:0 auto 4px}.move-pad div{display:flex;gap:4px}.mobile-fire{position:absolute;right:24px;bottom:35px;width:70px;height:70px;border-radius:50%;background:rgba(212,252,88,.17);font:700 13px var(--display);letter-spacing:.08em}
@keyframes pulse{50%{opacity:.45;box-shadow:0 0 3px var(--acid)}}@keyframes loaderpulse{to{transform:scale(.88);opacity:.55}}
@media(max-width:700px){.topbar{height:60px;padding:0 18px}.brand{font-size:18px}.brand-mark{width:29px;height:29px}.top-center{font-size:8px}.icon-btn{padding:9px}.icon-btn span{display:none}.screen{inset:60px 0 0}.menu-screen{align-items:flex-end;background:linear-gradient(0deg,rgba(4,11,10,.98) 0%,rgba(4,11,10,.88) 51%,rgba(4,11,10,.08) 100%)}.menu-content{margin:0 22px 42px;width:calc(100% - 44px)}.menu-content h1{font-size:clamp(60px,16vw,86px)}.intro{margin:14px 0 18px}.mode-card{height:80px;padding:10px}.mode-card strong{font-size:14px}.menu-side-note{display:none}.controls-note{font-size:7px}.hud{inset:60px 0 0}.hud-top-left{left:16px;top:17px;gap:12px}.stage-card{min-width:53px;padding-right:10px}.stage-card strong{font-size:37px}.boss-card strong{font-size:17px}.hud-label{font-size:7px}.boss-meta{gap:7px;font-size:7px}.hud-top-right{right:14px;top:15px}.objective-tag{display:none}.pause-btn{padding:8px}.boss-health-wrap{top:90px;width:48vw}.hud-bottom-left{left:17px;bottom:22px;width:155px}.health-icon{width:27px;height:27px}.health-line strong{font-size:25px}.hud-bottom-right{right:16px;bottom:21px;gap:10px}.ammo-block>div strong{font-size:32px}.ammo-block .hud-label{font-size:6px}.reload-btn{padding:8px}.reload-btn span,.reload-btn kbd{display:none}.mobile-controls{display:block}.crosshair{top:50%}.modal-card{padding:30px 26px}.modal-card h2{font-size:52px}.modal-screen{inset:0}.toast{top:125px;font-size:17px}}
@media(min-width:701px) and (max-height:700px){.menu-content{transform:scale(.86);transform-origin:left center}.hud-bottom-left,.hud-bottom-right{bottom:18px}.menu-side-note{bottom:4%}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('game-canvas');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x111b18);
scene.fog = new THREE.FogExp2(0x111b18, 0.012);
const camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, 0.1, 180);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

scene.add(new THREE.HemisphereLight(0xb9dbcf, 0x18231d, 1.6));
const keyLight = new THREE.DirectionalLight(0xd0e9c2, 2.7);
keyLight.position.set(-16, 24, 9); keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024); keyLight.shadow.camera.left = -35; keyLight.shadow.camera.right = 35; keyLight.shadow.camera.top = 35; keyLight.shadow.camera.bottom = -35;
scene.add(keyLight);
const rimLight = new THREE.PointLight(0x82c4a4, 55, 60); rimLight.position.set(13, 9, -18); scene.add(rimLight);
const arena = new THREE.Group(); scene.add(arena);
const solids = [];
const mat = (color, roughness = .78, metalness = .1, emissive = 0x000000, intensity = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness, emissive, emissiveIntensity: intensity });
const groundMat = mat(0x364039, .96);
const concrete = mat(0x566057, .88, .15);
const darkMetal = mat(0x17221e, .46, .62);
const acidMat = mat(0xc8f451, .3, .25, 0x91d52b, 1.2);
const orangeMat = mat(0xff6645, .4, .18, 0x9e2418, 1.4);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(110, 110), groundMat);
floor.rotation.x = -Math.PI / 2; floor.position.y = -0.07; floor.receiveShadow = true; arena.add(floor);
const grid = new THREE.GridHelper(100, 50, 0x91b279, 0x53604f); grid.position.y = -0.045; grid.material.transparent = true; grid.material.opacity = .22; arena.add(grid);
function addBox(x, y, z, sx, sy, sz, material, solid = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), material);
  mesh.position.set(x, y, z); mesh.castShadow = true; mesh.receiveShadow = true; arena.add(mesh);
  if (solid) solids.push({ x, z, sx, sz }); return mesh;
}
// Ruined perimeter walls and chunky cover make the arena feel like a real place.
addBox(0, 3, -33, 72, 6, 2.2, darkMetal); addBox(0, 3, 33, 72, 6, 2.2, darkMetal);
addBox(-36, 3, 0, 2.2, 6, 68, darkMetal); addBox(36, 3, 0, 2.2, 6, 68, darkMetal);
for (let i = 0; i < 10; i++) {
  const x = (i % 5 - 2) * 13 + (i > 4 ? 3 : 0), z = i < 5 ? -15 : 14;
  const h = 2.3 + (i % 3) * .5;
  addBox(x, h / 2, z, 3.2, h, 2.5, i % 2 ? concrete : darkMetal);
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(2.5, .12, .06), acidMat); stripe.position.set(x, h - .35, z + 1.29); arena.add(stripe);
}
for (let i = 0; i < 8; i++) {
  const x = i % 2 ? -31 : 31, z = -27 + i * 7.5;
  const pillar = addBox(x, 4, z, 1.6, 8, 1.6, concrete);
  const band = new THREE.Mesh(new THREE.BoxGeometry(1.7, .2, 1.7), i % 2 ? acidMat : orangeMat); band.position.set(x, 6.7, z); arena.add(band);
}
// Center medallion and perimeter lights.
const ring = new THREE.Mesh(new THREE.TorusGeometry(5.4, .11, 8, 64), acidMat); ring.rotation.x = Math.PI / 2; ring.position.y = .03; arena.add(ring);
const centerDisc = new THREE.Mesh(new THREE.CircleGeometry(5.1, 64), mat(0x29352e, .8)); centerDisc.rotation.x = -Math.PI / 2; centerDisc.position.y = -.02; arena.add(centerDisc);
for (let i = 0; i < 16; i++) {
  const a = i * Math.PI / 8, x = Math.cos(a) * 30, z = Math.sin(a) * 28;
  const light = new THREE.PointLight(i % 2 ? 0xb7ec65 : 0xff6845, 6, 10); light.position.set(x, 2.5, z); scene.add(light);
  const orb = new THREE.Mesh(new THREE.SphereGeometry(.14, 8, 8), i % 2 ? acidMat : orangeMat); orb.position.copy(light.position); arena.add(orb);
}
const skyDust = new THREE.Group(); scene.add(skyDust);
for (let i = 0; i < 180; i++) {
  const dot = new THREE.Mesh(new THREE.SphereGeometry(.035 + Math.random() * .035, 5, 5), mat(i % 5 ? 0x98ac96 : 0xd5f985, .6, 0, i % 5 ? 0x263e2d : 0x9ad34d, .7));
  dot.position.set((Math.random() - .5) * 100, 5 + Math.random() * 35, (Math.random() - .5) * 100); skyDust.add(dot);
}

const names = ['THE WARDEN','IRON JACKAL','ASH TITAN','REDLINE','THE EXECUTOR','BONE MACHINE','NIGHTFALL','WARBRINGER','THE COLOSSUS','LAST LIGHT'];
const game = { mode: 'solo', active: false, paused: false, over: false, kills: 0, hp: 1000, ammo: 30, reserve: 999, score: 0, reloading: false, fireAt: 0, toastAt: 0, lastDamage: 0, pointerLocked: false };
const keys = new Set(), moveTouch = new Set();
const player = { pos: new THREE.Vector3(0, 1.7, 25), yaw: 0, pitch: 0 };
camera.position.copy(player.pos); camera.rotation.order = 'YXZ';
let boss = null, projectiles = [], allies = [], particles = [];
const gun = new THREE.Group();
const gunBody = new THREE.Mesh(new THREE.BoxGeometry(.22, .2, .75), darkMetal); gunBody.position.set(.35, -.27, -.58); gun.add(gunBody);
const gunTop = new THREE.Mesh(new THREE.BoxGeometry(.12, .08, .5), acidMat); gunTop.position.set(.35, -.15, -.64); gun.add(gunTop);
const gunBarrel = new THREE.Mesh(new THREE.CylinderGeometry(.055, .065, .42, 12), mat(0x101715, .32, .75)); gunBarrel.rotation.x = Math.PI / 2; gunBarrel.position.set(.35, -.25, -.98); gun.add(gunBarrel);
const gunGrip = new THREE.Mesh(new THREE.BoxGeometry(.11, .26, .16), concrete); gunGrip.position.set(.35, -.46, -.39); gunGrip.rotation.x = -.18; gun.add(gunGrip);
const muzzleFlash = new THREE.Mesh(new THREE.SphereGeometry(.13, 8, 8), mat(0xffec94, .2, 0, 0xffd24d, 4)); muzzleFlash.position.set(.35, -.25, -1.2); muzzleFlash.visible = false; gun.add(muzzleFlash);
camera.add(gun); scene.add(camera);

function makeBoss() {
  const stage = Math.floor(game.kills / 10) + 1, index = game.kills % 10;
  const root = new THREE.Group(); root.position.set((Math.random() - .5) * 14, 0, -13 - Math.random() * 4); scene.add(root);
  const armor = new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(.37 - stage * .018, .22, .22 + (index % 3) * .035), roughness: .48, metalness: .56, emissive: 0x17231b, emissiveIntensity: .55 });
  const black = darkMetal;
  function part(geometry, material, x, y, z, scale) { const mesh = new THREE.Mesh(geometry, material); mesh.position.set(x,y,z); if (scale) mesh.scale.set(...scale); mesh.castShadow = true; mesh.receiveShadow = true; root.add(mesh); return mesh; }
  const body = part(new THREE.CylinderGeometry(.48,.62,1.35,8), armor, 0, 1.45, 0, [1,1,1]);
  body.rotation.z = .04;
  part(new THREE.BoxGeometry(1.3,.42,.55), armor, 0, 1.92, 0);
  part(new THREE.SphereGeometry(.38,10,8), black, 0, 2.48, -.04, [1,1.12,.9]);
  const eye = part(new THREE.BoxGeometry(.44,.1,.09), orangeMat, 0, 2.52, -.4); eye.userData.isEye = true;
  for (const side of [-1,1]) {
    part(new THREE.CylinderGeometry(.18,.22,.85,7), armor, side*.77, 1.47, 0, [1,1,.9]).rotation.z = side*.16;
    part(new THREE.CylinderGeometry(.24,.2,.76,7), black, side*.37, .52, 0, [1,1,.9]);
    part(new THREE.BoxGeometry(.3,.56,.32), armor, side*.48, 1.57, -.17);
    part(new THREE.BoxGeometry(.08,.35,.1), acidMat, side*.78, 1.45, -.22);
  }
  const hp = 140 + stage * 48 + index * 9;
  boss = { root, hp, maxHp: hp, speed: 1.1 + stage * .045, nextShot: performance.now() + 1800, name: names[index], parts: root.children };
  $('stage-value').textContent = String(stage).padStart(2,'0');
  $('boss-name').textContent = boss.name; $('boss-number').textContent = `BOSS ${String(index+1).padStart(2,'0')}`;
  $('kills-count').textContent = String(game.kills).padStart(2,'0'); updateBossHud();
  toast(`${boss.name} // INCOMING`);
}
function updateBossHud() { if (!boss) return; const pct = Math.max(0, boss.hp / boss.maxHp * 100); $('boss-health-fill').style.width = `${pct}%`; $('boss-hp-text').textContent = `${Math.ceil(pct)}%`; }

function addAlly(slot) {
  const group = new THREE.Group(); const allyMat = mat(slot ? 0x71879a : 0x8e9b75, .58, .38);
  const torso = new THREE.Mesh(new THREE.CylinderGeometry(.28,.34,.92,7), allyMat); torso.position.y = 1.18; group.add(torso);
  const head = new THREE.Mesh(new THREE.SphereGeometry(.23,8,7), darkMetal); head.position.y = 1.82; group.add(head);
  const visor = new THREE.Mesh(new THREE.BoxGeometry(.27,.07,.07), acidMat); visor.position.set(0,1.84,-.19); group.add(visor);
  const rifle = new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.58), darkMetal); rifle.position.set(.31,1.3,-.24); group.add(rifle);
  group.position.set(slot ? 2.2 : -2.2, 0, 26); scene.add(group);
  allies.push({ group, slot, nextShot: performance.now() + 800 + slot * 450 });
}

function startRun() {
  game.mode = document.querySelector('.mode-card.selected')?.dataset.mode || 'solo';
  game.active = true; game.paused = false; game.over = false; game.kills = 0; game.hp = 1000; game.ammo = 30; game.reserve = 999; game.reloading = false;
  player.pos.set(0,1.7,25); player.yaw = 0; player.pitch = 0; camera.position.copy(player.pos); camera.rotation.set(0,0,0);
