const groundMat = mat(0x364039, .96);
const concrete = mat(0x566057, .88, .15);
const darkMetal = mat(0x17221e, .46, .62);
const acidMat = mat(0xc8f451, .3, .25, 0x91d52b, 1.2);
const orangeMat = mat(0xff6645, .4, .18, 0x9e2418, 1.4);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(110, 110), groundMat);
floor.rotation.x = -Math.PI / 2; floor.position.y = -0.07; floor.receiveShadow = true; arena.add(floor);
const grid = new THREE.GridHelper(100, 50, 0x91b279, 0x53604f); grid.position.y = -0.045; grid.material.transparent = true; grid.material.opacity = .22; arena.add(grid);
function addBox(x, y, z, sx, sy, sz, material, solid = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), material);
  mesh.position.set(x, y, z); mesh.castShadow = true; mesh.receiveShadow = true; arena.add(mesh);
  if (solid) solids.push({ x, z, sx, sz }); return mesh;
}
// Ruined perimeter walls and chunky cover make the arena feel like a real place.
addBox(0, 3, -33, 72, 6, 2.2, darkMetal); addBox(0, 3, 33, 72, 6, 2.2, darkMetal);
addBox(-36, 3, 0, 2.2, 6, 68, darkMetal); addBox(36, 3, 0, 2.2, 6, 68, darkMetal);
for (let i = 0; i < 10; i++) {
  const x = (i % 5 - 2) * 13 + (i > 4 ? 3 : 0), z = i < 5 ? -15 : 14;
  const h = 2.3 + (i % 3) * .5;
  addBox(x, h / 2, z, 3.2, h, 2.5, i % 2 ? concrete : darkMetal);
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(2.5, .12, .06), acidMat); stripe.position.set(x, h - .35, z + 1.29); arena.add(stripe);
}
for (let i = 0; i < 8; i++) {
  const x = i % 2 ? -31 : 31, z = -27 + i * 7.5;
  const pillar = addBox(x, 4, z, 1.6, 8, 1.6, concrete);
  const band = new THREE.Mesh(new THREE.BoxGeometry(1.7, .2, 1.7), i % 2 ? acidMat : orangeMat); band.position.set(x, 6.7, z); arena.add(band);
}
// Center medallion and perimeter lights.
const ring = new THREE.Mesh(new THREE.TorusGeometry(5.4, .11, 8, 64), acidMat); ring.rotation.x = Math.PI / 2; ring.position.y = .03; arena.add(ring);
const centerDisc = new THREE.Mesh(new THREE.CircleGeometry(5.1, 64), mat(0x29352e, .8)); centerDisc.rotation.x = -Math.PI / 2; centerDisc.position.y = -.02; arena.add(centerDisc);
for (let i = 0; i < 16; i++) {
  const a = i * Math.PI / 8, x = Math.cos(a) * 30, z = Math.sin(a) * 28;
  const light = new THREE.PointLight(i % 2 ? 0xb7ec65 : 0xff6845, 6, 10); light.position.set(x, 2.5, z); scene.add(light);
  const orb = new THREE.Mesh(new THREE.SphereGeometry(.14, 8, 8), i % 2 ? acidMat : orangeMat); orb.position.copy(light.position); arena.add(orb);
}

